style.css:
body {
  background: url('https://i.imgur.com/8KQlXJc.gif') repeat;
  font-family: Comic Sans MS, Arial, sans-serif;
  color: yellow;
  text-align: center;
}

h1 {
  color: lime;
  text-shadow: 2px 2px 4px red;
  font-size: 36px;
}

a:link { color: red; text-decoration: underline; }
a:visited { color: purple; }
a:hover { color: blue; text-decoration: blink; }

table {
  border: 2px dashed red;
  margin: 0 auto;
}

td {
  background: silver;
  padding: 10px;
}

blink {
  color: fuchsia;
  font-size: 20px;
}
